  1→import React, { useEffect, useEffectEvent, useMemo, useState } from 'react';
  2→import type { CSSProperties, SetStateAction } from 'react';
  3→import { useTranslation } from 'react-i18next';
  4→import { useSwipeable } from 'react-swipeable';
  5→
  6→import { Button, ButtonWithLoading } from '@actual-app/components/button';
  7→import { useResponsive } from '@actual-app/components/hooks/useResponsive';
  8→import { AnimatedLoading } from '@actual-app/components/icons/AnimatedLoading';
  9→import { SvgDelete } from '@actual-app/components/icons/v0';
 10→import { SpaceBetween } from '@actual-app/components/space-between';
 11→import { styles } from '@actual-app/components/styles';
 12→import { Text } from '@actual-app/components/text';
 13→import { theme } from '@actual-app/components/theme';
 14→import { View } from '@actual-app/components/view';
 15→import { css } from '@emotion/css';
 16→import { animated, to, useSpring } from '@react-spring/web';
 17→
 18→import { Link } from './common/Link';
 19→import { MODAL_Z_INDEX } from './common/Modal';
 20→
 21→import { removeNotification } from '@desktop-client/notifications/notificationsSlice';
 22→import type { NotificationWithId } from '@desktop-client/notifications/notificationsSlice';
 23→import { useDispatch, useSelector } from '@desktop-client/redux';
 24→
 25→// Notification stacking configuration
 26→const MAX_VISIBLE_NOTIFICATIONS = 3; // Maximum number of notifications visible in the stack
 27→const SCALE_MULTIPLIER = 0.05; // Scale reduction per stacked notification
 28→const OPACITY_MULTIPLIER = 0.2; // Opacity reduction per stacked notification
 29→const MIN_OPACITY = 1; // Minimum opacity for stacked notifications
 30→const Y_OFFSET_PER_LEVEL = -20; // Vertical offset in pixels per stacked notification
 31→const BASE_Z_INDEX = 10; // Base z-index for notification stacking
 32→
 33→function compileMessage(
 34→  message: string,
 35→  actions: Record<string, () => void>,
 36→  setLoading: (arg: SetStateAction<boolean>) => void,
 37→  onRemove?: () => void,
 38→) {
 39→  return (
 40→    <SpaceBetween direction="vertical" gap={10}>
 41→      {message.split(/\n\n/).map((paragraph, idx) => {
 42→        const parts = paragraph.split(/(\[[^\]]*\]\([^)]*\))/g);
 43→
 44→        return (
 45→          <Text key={idx} style={{ lineHeight: '1.4em' }}>
 46→            {parts.map((part, idx) => {
 47→              const match = part.match(/\[([^\]]*)\]\(([^)]*)\)/);
 48→              if (match) {
 49→                const [_, text, href] = match;
 50→
 51→                if (href[0] === '#') {
 52→                  const actionName = href.slice(1);
 53→                  return (
 54→                    <Link
 55→                      variant="text"
 56→                      key={idx}
 57→                      onClick={async e => {
 58→                        e.preventDefault();
 59→                        if (actions[actionName]) {
 60→                          setLoading(true);
 61→                          await actions[actionName]();
 62→                          onRemove?.();
 63→                        }
 64→                      }}
 65→                    >
 66→                      {text}
 67→                    </Link>
 68→                  );
 69→                }
 70→
 71→                return (
 72→                  <Link
 73→                    variant="external"
 74→                    linkColor="purple"
 75→                    key={idx}
 76→                    to={match[2]}
 77→                  >
 78→                    {match[1]}
 79→                  </Link>
 80→                );
 81→              }
 82→              return <Text key={idx}>{part}</Text>;
 83→            })}
 84→          </Text>
 85→        );
 86→      })}
 87→    </SpaceBetween>
 88→  );
 89→}
 90→
 91→function Notification({
 92→  notification,
 93→  onRemove,
 94→  index,
 95→  isInteractive,
 96→}: {
 97→  notification: NotificationWithId;
 98→  onRemove: () => void;
 99→  index: number;
100→  isInteractive: boolean;
101→}) {
102→  const { t } = useTranslation();
103→  const {
104→    type,
105→    title,
106→    message,
107→    pre,
108→    messageActions,
109→    sticky,
110→    internal,
111→    button,
112→    timeout,
113→  } = notification;
114→
115→  const [loading, setLoading] = useState(false);
116→  const [overlayLoading, setOverlayLoading] = useState(false);
117→
118→  const connected = useEffectEvent(() => {
119→    if (type === 'error' && internal) {
120→      console.error('Internal error:', internal);
121→    }
122→
123→    if (!sticky) {
124→      setTimeout(onRemove, timeout || 6500);
125→    }
126→  });
127→  useEffect(() => connected(), []);
128→
129→  const positive = type === 'message';
130→  const error = type === 'error';
131→
132→  const processedMessage = useMemo(
133→    () =>
134→      compileMessage(
135→        message,
136→        messageActions ?? {},
137→        setOverlayLoading,
138→        onRemove,
139→      ),
140→    [message, messageActions, onRemove, setOverlayLoading],
141→  );
142→
143→  const { isNarrowWidth } = useResponsive();
144→  const narrowStyle: CSSProperties = isNarrowWidth
145→    ? { minHeight: styles.mobileMinHeight }
146→    : {};
147→
148→  // Calculate stacking properties based on index (scales for any number of notifications)
149→  const scale = 1.0 - index * SCALE_MULTIPLIER;
150→  const stackOpacity = Math.max(MIN_OPACITY, 1.0 - index * OPACITY_MULTIPLIER);
151→  const zIndex = BASE_Z_INDEX - index;
152→
153→  const yOffset = index * Y_OFFSET_PER_LEVEL;
154→
155→  const [isSwiped, setIsSwiped] = useState(false);
156→  const [spring, api] = useSpring(() => ({
157→    x: 0,
158→    y: yOffset,
159→    opacity: stackOpacity,
160→    scale,
161→  }));
162→
163→  // Update scale, opacity, and y-position when index changes
164→  useEffect(() => {
165→    api.start({ scale, opacity: stackOpacity, y: yOffset });
166→  }, [index, scale, stackOpacity, yOffset, api]);
167→
168→  const swipeHandlers = useSwipeable({
169→    onSwiping: ({ deltaX }) => {
170→      if (!isSwiped) {
171→        api.start({ x: deltaX });
172→      }
173→    },
174→    onSwiped: ({ velocity, deltaX }) => {
175→      // Distance to trigger deletion
176→      const threshold = 100;
177→      const direction = deltaX > 0 ? 1 : -1;
178→
179→      if (Math.abs(deltaX) > threshold || velocity > 0.5) {
180→        // Animate out & remove item after animation
181→        api.start({
182→          x: direction * 1000,
183→          opacity: 0,
184→          onRest: onRemove,
185→        });
186→        setIsSwiped(true);
187→      } else {
188→        // Reset position if not swiped far enough
189→        api.start({ x: 0 });
190→      }
191→    },
192→    trackMouse: true,
193→  });
194→
195→  return (
196→    <animated.div
197→      role="alert"
198→      style={{
199→        position: 'absolute',
200→        bottom: 0,
201→        left: 0,
202→        right: 0,
203→        zIndex,
204→        // Combine translateX, translateY and scale transforms
205→        transform: to(
206→          [spring.x, spring.y, spring.scale],
207→          (x, y, s) => `translateX(${x}px) translateY(${y}px) scale(${s})`,
208→        ),
209→        opacity: spring.opacity,
210→        pointerEvents: isInteractive ? 'auto' : 'none',
211→        color: positive
212→          ? theme.noticeText
213→          : error
214→            ? theme.errorTextDark
215→            : theme.warningTextDark,
216→        // Prevents scrolling conflicts
217→        touchAction: isInteractive ? 'none' : 'auto',
218→      }}
219→      {...(isInteractive ? swipeHandlers : {})}
220→    >
221→      <View
222→        style={{
223→          position: 'relative',
224→          padding: '14px 14px',
225→          paddingRight: 40,
226→          borderRadius: 8,
227→          ...styles.mediumText,
228→          backgroundColor: positive
229→            ? theme.noticeBackgroundLight
230→            : error
231→              ? theme.errorBackground
232→              : theme.warningBackground,
233→          borderTop: `3px solid ${
234→            positive
235→              ? theme.noticeBorder
236→              : error
237→                ? theme.errorBorder
238→                : theme.warningBorder
239→          }`,
240→          ...styles.shadowLarge,
241→          maxWidth: 550,
242→          '& a': { color: 'currentColor' },
243→        }}
244→      >
245→        {/* Close button in top right corner */}
246→        <Button
247→          variant="bare"
248→          aria-label={t('Close')}
249→          style={{
250→            position: 'absolute',
251→            top: 8,
252→            right: 8,
253→            padding: 8,
254→            color: 'currentColor',
255→            opacity: 0.7,
256→          }}
257→          onPress={onRemove}
258→        >
259→          <SvgDelete style={{ width: 10, height: 10 }} />
260→        </Button>
261→
262→        {/* Content and action button layout */}
263→        <SpaceBetween
264→          direction="vertical"
265→          gap={10}
266→          style={{ alignItems: 'flex-start' }}
267→        >
268→          {title && (
269→            <View
270→              style={{
271→                ...styles.mediumText,
272→                fontWeight: 700,
273→                paddingRight: 20,
274→              }}
275→            >
276→              {title}
277→            </View>
278→          )}
279→
280→          {/* Message and button on same row */}
281→          <SpaceBetween
282→            wrap={false}
283→            gap={10}
284→            style={{ width: '100%', alignItems: 'flex-start' }}
285→          >
286→            <View style={{ flex: 1, minWidth: 0 }}>{processedMessage}</View>
287→            {button && (
288→              <ButtonWithLoading
289→                variant="bare"
290→                isLoading={loading}
291→                onPress={async () => {
292→                  setLoading(true);
293→                  await button.action();
294→                  onRemove();
295→                  setLoading(false);
296→                }}
297→                className={css({
298→                  backgroundColor: 'transparent',
299→                  border: `1px solid ${
300→                    positive
301→                      ? theme.noticeBorder
302→                      : error
303→                        ? theme.errorBorder
304→                        : theme.warningBorder
305→                  }`,
306→                  color: 'currentColor',
307→                  ...styles.mediumText,
308→                  flexShrink: 0,
309→                  '&[data-hovered], &[data-pressed]': {
310→                    backgroundColor: positive
311→                      ? theme.noticeBackground
312→                      : error
313→                        ? theme.errorBackground
314→                        : theme.warningBackground,
315→                  },
316→                  ...narrowStyle,
317→                })}
318→              >
319→                {button.title}
320→              </ButtonWithLoading>
321→            )}
322→          </SpaceBetween>
323→
324→          {pre
325→            ? pre.split('\n\n').map((text, idx) => (
326→                <View
327→                  key={idx}
328→                  style={{
329→                    whiteSpace: 'pre-wrap',
330→                    fontFamily: 'monospace',
331→                    fontSize: 12,
332→                    backgroundColor: 'rgba(0, 0, 0, .05)',
333→                    padding: 10,
334→                    borderRadius: 4,
335→                    width: '100%',
336→                  }}
337→                >
338→                  {text}
339→                </View>
340→              ))
341→            : null}
342→        </SpaceBetween>
343→      </View>
344→      {overlayLoading && (
345→        <View
346→          style={{
347→            position: 'absolute',
348→            top: 0,
349→            left: 0,
350→            right: 0,
351→            bottom: 0,
352→            backgroundColor: theme.tableBackground,
353→            alignItems: 'center',
354→            justifyContent: 'center',
355→          }}
356→        >
357→          <AnimatedLoading
358→            style={{ width: 20, height: 20, color: 'currentColor' }}
359→          />
360→        </View>
361→      )}
362→    </animated.div>
363→  );
364→}
