366→export function Notifications({ style }: { style?: CSSProperties }) {
367→  const dispatch = useDispatch();
368→  const { isNarrowWidth } = useResponsive();
369→  const notifications = useSelector(state => state.notifications.notifications);
370→  const notificationInset = useSelector(state => state.notifications.inset);
371→
372→  // Only show the last N notifications (newest first) for z-axis stacking
373→  // Reverse so newest notification (last in array) becomes index 0 (front)
374→  const visibleNotifications = notifications
375→    .slice(-MAX_VISIBLE_NOTIFICATIONS)
376→    .reverse();
377→
378→  return (
379→    <View
380→      style={{
381→        position: 'fixed',
382→        bottom: notificationInset?.bottom || 20,
383→        top: notificationInset?.top,
384→        right: notificationInset?.right || 13,
385→        left: notificationInset?.left || (isNarrowWidth ? 13 : undefined),
386→        zIndex: MODAL_Z_INDEX - 1,
387→        width: isNarrowWidth ? undefined : 400,
388→        ...style,
389→      }}
390→    >
391→      <View style={{ position: 'relative' }}>
392→        {visibleNotifications.map((note, index) => (
393→          <Notification
394→            key={note.id}
395→            notification={note}
396→            index={index}
397→            isInteractive={index === 0}
398→            onRemove={() => {
399→              if (note.onClose) {
400→                note.onClose();
401→              }
402→              dispatch(removeNotification({ id: note.id }));
403→            }}
404→          />
405→        ))}
406→      </View>
407→    </View>
408→  );
409→}
