  1→import { useEffect, useState } from 'react';
  2→
  3→import { useQuery } from '@tanstack/react-query';
  4→
  5→import { send } from 'loot-core/platform/client/connection';
  6→
  7→import { useSyncServerStatus } from './useSyncServerStatus';
  8→
  9→import { accountQueries } from '@desktop-client/accounts';
 10→import {
 11→  getUrgencyLevel,
 12→  type ConsentUrgency,
 13→} from '@desktop-client/utils/consent-urgency';
 14→
 15→export type { ConsentUrgency } from '@desktop-client/utils/consent-urgency';
 16→
 17→/**
 18→ * Checks whether Enable Banking is configured on the sync-server
 19→ * (JWT key present and valid).
 20→ *
 21→ * Returns:
 22→ * - configured: true when the server has a working Enable Banking key
 23→ * - isLoading: true while the status check is in flight
 24→ */
 25→export function useEnableBankingStatus() {
 26→  const [configured, setConfigured] = useState<boolean | null>(null);
 27→  const [isLoading, setIsLoading] = useState(false);
 28→  const status = useSyncServerStatus();
 29→
 30→  useEffect(() => {
 31→    async function fetch() {
 32→      setIsLoading(true);
 33→
 34→      const results = await send('enablebanking-status');
 35→
 36→      setConfigured(results?.configured || false);
 37→      setIsLoading(false);
 38→    }
 39→
 40→    if (status === 'online') {
 41→      fetch();
 42→    }
 43→  }, [status]);
 44→
 45→  return {
 46→    configured,
 47→    isLoading,
 48→  };
 49→}
 50→
 51→type SyncStatusEntry = {
 52→  synced_at: string | null; // ISO string (server converts from epoch integer)
 53→  status: string;
 54→  error_message: string | null;
 55→  transactions_added: number | null; // from eb_sync_log
 56→  transactions_updated: number | null; // from eb_sync_log
 57→  error_code: string | null; // from eb_sync_log
 58→  consent_valid_until: string | null; // NEW - ISO date from eb_sessions.valid_until
 59→  session_id: string | null; // NEW - for re-auth grouping
 60→  aspsp_name: string | null; // NEW - for banner display (e.g. "ING Bank connection expires March 15")
 61→  aspsp_country: string | null; // NEW - for re-auth createAuth country param
 62→};
 63→
 64→/**
 65→ * Fetches per-account Enable Banking sync status from the sync-server.
 66→ * Accepts an array of Actual account UUIDs (the standard `account.id` field).
 67→ *
 68→ * CRITICAL DEPENDENCY: This hook works correctly because
 69→ * `eb_account_map.actual_account_id` is populated at link time by the
 70→ * `enablebanking-accounts-link` IPC handler (Plan 02-03 Task 2), which
 71→ * calls POST /update-account-map to store the Actual UUID in the map.
 72→ * The /transactions route then uses `mapRow.actual_account_id` from that
 73→ * map when writing to `eb_sync_log`. Without this link-time population,
 74→ * the `actual_account_id` column would be NULL and queries here would
 75→ * return no results.
 76→ *
 77→ * Returns:
 78→ * - statuses: Record<string, SyncStatusEntry> keyed by Actual account UUID
 79→ * - isLoading: true while the fetch is in flight
 80→ */
 81→export function useEnableBankingSyncStatus(accountIds: string[]) {
 82→  const [statuses, setStatuses] = useState<Record<string, SyncStatusEntry>>({});
 83→  const [isLoading, setIsLoading] = useState(false);
 84→
 85→  // Stable key to avoid re-fetching on every render when the array
 86→  // reference changes but contents are the same
 87→  const accountIdsKey = accountIds.join(',');
 88→
 89→  useEffect(() => {
 90→    if (accountIds.length === 0) {
 91→      setStatuses({});
 92→      return;
 93→    }
 94→
 95→    async function fetch() {
 96→      setIsLoading(true);
 97→
 98→      const result = await send('enablebanking-sync-status', { accountIds });
 99→
100→      if (result && result.statuses) {
101→        setStatuses(result.statuses);
102→      } else {
103→        setStatuses({});
104→      }
105→
106→      setIsLoading(false);
107→    }
108→
109→    fetch();
110→    // eslint-disable-next-line react-hooks/exhaustive-deps
111→  }, [accountIdsKey]);
112→
113→  return {
114→    statuses,
115→    isLoading,
116→  };
117→}
118→
119→export type ConsentSession = {
120→  sessionId: string;
121→  aspspName: string | null;
122→  aspspCountry: string | null;
123→  validUntil: string | null;
124→  urgency: ConsentUrgency;
125→  accountIds: string[];
126→};
127→
128→/**
129→ * Self-contained hook that:
130→ * - Fetches all accounts via accountQueries.list()
131→ * - Filters to Enable Banking-linked accounts
132→ * - Groups by session_id with urgency calculation
133→ * - Returns sessions sorted by urgency (expired first)
134→ *
135→ * Urgency thresholds:
136→ * - expired: consent_valid_until is in the past
137→ * - urgent: within 7 days
138→ * - soon: within 14 days
139→ * - ok: more than 14 days away (not returned in sessions array)
140→ */
141→export function useConsentExpiry(): {
142→  sessions: ConsentSession[];
143→  worstUrgency: ConsentUrgency;
144→} {
145→  const { data: accounts } = useQuery(accountQueries.list());
146→
147→  const ebAccountIds = (accounts ?? [])
148→    .filter(a => a.account_sync_source === 'enableBanking')
149→    .map(a => a.id);
150→
151→  const { statuses } = useEnableBankingSyncStatus(ebAccountIds);
152→
153→  // Group accounts by session_id
154→  const sessionMap = new Map<string, ConsentSession>();
155→
156→  for (const accountId of ebAccountIds) {
157→    const entry = statuses[accountId];
158→    if (!entry || !entry.session_id) continue;
159→
160→    const sessionId = entry.session_id;
161→
162→    if (!sessionMap.has(sessionId)) {
163→      const validUntil = entry.consent_valid_until;
164→      let urgency: ConsentUrgency = 'ok';
165→
166→      if (validUntil) {
167→        const now = new Date();
168→        const expiry = new Date(validUntil);
169→        const msUntilExpiry = expiry.getTime() - now.getTime();
170→        const daysUntilExpiry = msUntilExpiry / (1000 * 60 * 60 * 24);
171→        urgency = getUrgencyLevel(daysUntilExpiry);
172→      }
173→
174→      sessionMap.set(sessionId, {
175→        sessionId,
176→        aspspName: entry.aspsp_name,
177→        aspspCountry: entry.aspsp_country,
178→        validUntil: entry.consent_valid_until,
179→        urgency,
180→        accountIds: [],
181→      });
182→    }
183→
184→    sessionMap.get(sessionId)!.accountIds.push(accountId);
185→  }
186→
187→  // Only surface sessions that need attention (not 'ok')
188→  const urgencyOrder: Record<ConsentUrgency, number> = {
189→    expired: 0,
190→    urgent: 1,
191→    soon: 2,
192→    ok: 3,
193→  };
194→
195→  const sessions = Array.from(sessionMap.values())
196→    .filter(s => s.urgency !== 'ok')
197→    .sort((a, b) => urgencyOrder[a.urgency] - urgencyOrder[b.urgency]);
198→
199→  const worstUrgency: ConsentUrgency =
200→    sessions.length > 0 ? sessions[0].urgency : 'ok';
201→
202→  return { sessions, worstUrgency };
203→}
