 8→/**
 9→ * Urgency level for a consent session.
10→ * - expired: consent_valid_until is in the past
11→ * - urgent: within 7 days
12→ * - soon: within 14 days
13→ * - ok: more than 14 days away
14→ */
15→export type ConsentUrgency = 'expired' | 'urgent' | 'soon' | 'ok';
16→
17→/**
18→ * Derive urgency level from days until expiry.
19→ * Thresholds: <=0 → expired, <=7 → urgent, <=14 → soon, else → ok
20→ */
21→export function getUrgencyLevel(daysUntilExpiry: number): ConsentUrgency {
22→  if (daysUntilExpiry <= 0) {
23→    return 'expired';
24→  } else if (daysUntilExpiry <= 7) {
25→    return 'urgent';
26→  } else if (daysUntilExpiry <= 14) {
27→    return 'soon';
28→  }
29→  return 'ok';
30→}
