 1→// [eb] Custom error classes for Enable Banking error handling.
 2→// Using named classes (not anonymous class expressions) so that instanceof
 3→// checks and error.name remain reliable across module boundaries.
 4→
 5→export class EnableBankingError extends Error {
 6→  errorCode?: string;
 7→
 8→  constructor(message: string, errorCode?: string) {
 9→    super(message);
10→    this.name = 'EnableBankingError';
11→    this.errorCode = errorCode;
