 10→export type Notification = {
 11→  id?: string | undefined;
 12→  type?: 'message' | 'error' | 'warning' | undefined;
 13→  pre?: string | undefined;
 14→  title?: string | undefined;
 15→  message: string;
 16→  sticky?: boolean | undefined;
 17→  timeout?: number | undefined;
 18→  button?:
 19→    | {
 20→        title: string;
 21→        action: () => void | Promise<void>;
 22→      }
 23→    | undefined;
 24→  messageActions?: Record<string, () => void> | undefined;
 25→  onClose?: (() => void) | undefined;
 26→  internal?: string | undefined;
 27→};
 28→export type NotificationWithId = Notification & { id: string };
 29→
 30→type NotificationsState = {
 31→  notifications: NotificationWithId[];
 32→  inset?: {
 33→    bottom?: number;
 34→    top?: number;
 35→    right?: number;
 36→    left?: number;
 37→  };
 38→};
 39→
 40→const initialState: NotificationsState = {
 41→  notifications: [],
 42→  inset: {},
 43→};
 44→
 45→type AddNotificationPayload = {
 46→  notification: Notification;
 47→};
 48→type RemoveNotificationPayload = {
 49→  id: NotificationWithId['id'];
 50→};
 51→type SetNotificationInsetPayload = {
 52→  inset: NotificationsState['inset'];
 53→} | null;
 54→
 55→const notificationsSlice = createSlice({
 56→  name: sliceName,
 57→  initialState,
 58→  reducers: {
 59→    addNotification(state, action: PayloadAction<AddNotificationPayload>) {
 60→      const notification = {
 61→        ...action.payload.notification,
 62→        id: action.payload.notification.id || uuidv4(),
 63→      };
 64→
 65→      if (state.notifications.find(n => n.id === notification.id)) {
 66→        return;
 67→      }
 68→      state.notifications = [...state.notifications, notification];
 69→    },
 70→    addGenericErrorNotification(state) {
 71→      const notification: NotificationWithId = {
 72→        id: uuidv4(),
 73→        type: 'error',
 74→        message: t(
 75→          'Something internally went wrong. You may want to restart the app if anything looks wrong. ' +
 76→            'Please report this as a new issue on GitHub.',
 77→        ),
 78→      };
 79→      state.notifications = [...state.notifications, notification];
 80→    },
 81→    removeNotification(
 82→      state,
 83→      action: PayloadAction<RemoveNotificationPayload>,
 84→    ) {
 85→      state.notifications = state.notifications.filter(
 86→        notif => notif.id !== action.payload.id,
 87→      );
 88→    },
 89→    setNotificationInset(
 90→      state,
 91→      action: PayloadAction<SetNotificationInsetPayload>,
 92→    ) {
 93→      state.inset = action.payload?.inset ? action.payload.inset : {};
 94→    },
 95→  },
 96→  extraReducers: builder => {
 97→    builder.addCase(resetApp, () => initialState);
 98→  },
 99→});
