230→/**
231→ * Graduated consent expiry banner displayed at the top of FinancesApp.
232→ *
233→ * Self-contained: fetches its own data via useConsentExpiry().
234→ * No props needed - just drop it into the JSX.
235→ *
236→ * Colors:
237→ * - red (errorText/errorBackground): expired consent
238→ * - orange (warningText/warningBackground): within 7 days
239→ * - yellow (noticeText/noticeBackground): within 14 days
240→ *
241→ * Dismissible per day per session via localStorage.
242→ * Re-appears daily until consent is renewed.
243→ */
244→export function ConsentExpiryBanner() {
245→  const { sessions } = useConsentExpiry();
246→  const [, forceUpdate] = React.useReducer(x => x + 1, 0);
247→
248→  // Clean up old consent dismiss keys from localStorage on mount.
249→  // Uses two-pass approach: collect keys first, then delete.
250→  // Deleting during index iteration corrupts the index and skips keys.
251→  React.useEffect(() => {
252→    const today = new Date().toDateString();
253→    const keysToDelete: string[] = [];
254→    for (let i = 0; i < localStorage.length; i++) {
255→      const key = localStorage.key(i);
256→      if (key?.startsWith('consent-dismissed-') && !key.endsWith(today)) {
257→        keysToDelete.push(key);
258→      }
259→    }
260→    for (const key of keysToDelete) {
261→      localStorage.removeItem(key);
262→    }
263→  }, []);
264→
265→  // Filter out dismissed sessions
266→  const visibleSessions = sessions.filter(s => !isDismissed(s.sessionId));
267→
268→  if (visibleSessions.length === 0) {
269→    return null;
270→  }
271→
272→  if (visibleSessions.length === 1) {
273→    return (
274→      <SessionBanner session={visibleSessions[0]} onDismiss={forceUpdate} />
275→    );
276→  }
277→
278→  return (
279→    <MultiSessionBanner sessions={visibleSessions} onDismiss={forceUpdate} />
280→  );
281→}
