119→export type ConsentSession = {
120→  sessionId: string;
121→  aspspName: string | null;
122→  aspspCountry: string | null;
123→  validUntil: string | null;
124→  urgency: ConsentUrgency;
125→  accountIds: string[];
126→};
127→
128→/**
129→ * Self-contained hook that:
130→ * - Fetches all accounts via accountQueries.list()
131→ * - Filters to Enable Banking-linked accounts
132→ * - Groups by session_id with urgency calculation
133→ * - Returns sessions sorted by urgency (expired first)
134→ *
135→ * Urgency thresholds:
136→ * - expired: consent_valid_until is in the past
137→ * - urgent: within 7 days
138→ * - soon: within 14 days
139→ * - ok: more than 14 days away (not returned in sessions array)
140→ */
141→export function useConsentExpiry(): {
142→  sessions: ConsentSession[];
143→  worstUrgency: ConsentUrgency;
144→} {
145→  const { data: accounts } = useQuery(accountQueries.list());
146→
147→  const ebAccountIds = (accounts ?? [])
148→    .filter(a => a.account_sync_source === 'enableBanking')
149→    .map(a => a.id);
150→
151→  const { statuses } = useEnableBankingSyncStatus(ebAccountIds);
152→
153→  // Group accounts by session_id
154→  const sessionMap = new Map<string, ConsentSession>();
155→
156→  for (const accountId of ebAccountIds) {
157→    const entry = statuses[accountId];
158→    if (!entry || !entry.session_id) continue;
159→
160→    const sessionId = entry.session_id;
161→
162→    if (!sessionMap.has(sessionId)) {
163→      const validUntil = entry.consent_valid_until;
164→      let urgency: ConsentUrgency = 'ok';
165→
166→      if (validUntil) {
167→        const now = new Date();
168→        const expiry = new Date(validUntil);
169→        const msUntilExpiry = expiry.getTime() - now.getTime();
170→        const daysUntilExpiry = msUntilExpiry / (1000 * 60 * 60 * 24);
171→        urgency = getUrgencyLevel(daysUntilExpiry);
172→      }
173→
174→      sessionMap.set(sessionId, {
175→        sessionId,
176→        aspspName: entry.aspsp_name,
177→        aspspCountry: entry.aspsp_country,
178→        validUntil: entry.consent_valid_until,
179→        urgency,
180→        accountIds: [],
181→      });
182→    }
183→
184→    sessionMap.get(sessionId)!.accountIds.push(accountId);
185→  }
186→
187→  // Only surface sessions that need attention (not 'ok')
188→  const urgencyOrder: Record<ConsentUrgency, number> = {
189→    expired: 0,
190→    urgent: 1,
191→    soon: 2,
192→    ok: 3,
193→  };
194→
195→  const sessions = Array.from(sessionMap.values())
196→    .filter(s => s.urgency !== 'ok')
197→    .sort((a, b) => urgencyOrder[a.urgency] - urgencyOrder[b.urgency]);
198→
199→  const worstUrgency: ConsentUrgency =
200→    sessions.length > 0 ? sessions[0].urgency : 'ok';
201→
202→  return { sessions, worstUrgency };
203→}
