114→  // Mutex for background bank sync triggered by visibility/focus changes.
115→  // useRef persists across re-renders and effect re-creations (the effect
116→  // depends on staleThresholdHours, so a closure-scoped let would reset to
117→  // false whenever the pref changes, allowing concurrent syncs).
118→  const isSyncingRef = useRef(false);
