126→      // After CRDT sync completes, trigger background bank sync for accounts
127→      // whose last sync is older than the configurable stale threshold.
128→      // CRDT sync must finish first to avoid SQLite race conditions.
129→      try {
130→        const allAccounts = await send('accounts-get');
131→        const linkedAccounts = (allAccounts || []).filter(
132→          a => a.account_sync_source && a.account_id,
133→        );
134→        const effectiveThreshold = (staleThresholdHours ?? 6) * 60 * 60 * 1000;
135→        const now = Date.now();
136→
137→        // Fetch consent status in one call to filter out expired-consent
138→        // accounts before syncing (avoids wasted Enable Banking API calls).
139→        const linkedIds = linkedAccounts.map(a => a.id);
140→        // CRITICAL: send() returns { statuses } directly. post() already
141→        // unwraps responseData.data, so there is NO extra .data layer.
142→        const syncStatuses =
