  2→// [eb] Scheduled auto-sync: runs every 6 hours when ENABLE_AUTO_SYNC=true.
  3→// Calls Enable Banking service functions directly (no internal HTTP) so no
  4→// auth headers are needed. Per-session grouping ensures consent expiry is
  5→// checked once per bank connection and one user's failure doesn't block others.
  6→import cron from 'node-cron';
  7→
  8→import { getAccountDb } from './account-db.js';
  9→import {
 10→  getBalances,
 11→  getTransactions,
 12→} from './app-enablebanking/enablebanking-service.js';
 13→import {
 14→  RateLimitError,
 15→  SessionExpiredError,
 16→} from './app-enablebanking/errors.js';
 17→import { normalizeTransaction } from './app-enablebanking/utils.js';
 18→
 19→type AccountRow = {
 20→  actual_account_id: string;
 21→  eb_account_uid: string;
 22→  session_id: string;
 23→  valid_until: string | null;
 24→  aspsp_name: string | null;
 25→};
 26→
 27→async function syncOneAccount(account: AccountRow): Promise<void> {
 28→  const db = getAccountDb();
 29→
 30→  // Derive sinceDate from last successful sync (epoch integer -> YYYY-MM-DD).
 31→  const row = db.first(
 32→    'SELECT synced_at FROM eb_sync_log WHERE actual_account_id = ? ORDER BY id DESC LIMIT 1',
 33→    [account.actual_account_id],
 34→  );
 35→  const sinceDate = row?.synced_at
 36→    ? new Date(Number(row.synced_at) * 1000).toISOString().split('T')[0]
 37→    : new Date(Date.now() - 90 * 24 * 3600 * 1000).toISOString().split('T')[0];
 38→
 39→  const { booked, pending } = await getTransactions(
 40→    account.eb_account_uid,
 41→    sinceDate,
 42→  );
 43→  await getBalances(account.eb_account_uid);
 44→
 45→  const allNormalized = [
 46→    ...booked.map(t => normalizeTransaction(t, true)),
 47→    ...pending.map(t => normalizeTransaction(t, false)),
 48→  ];
 49→
 50→  db.mutate(
 51→    `INSERT INTO eb_sync_log (actual_account_id, eb_account_uid, status, transactions_added)
 52→     VALUES (?, ?, 'ok', ?)`,
 53→    [account.actual_account_id, account.eb_account_uid, allNormalized.length],
 54→  );
 55→
 56→  console.log(
 57→    `[scheduler] Synced ${account.actual_account_id}: ${allNormalized.length} transactions`,
 58→  );
 59→}
 60→
 61→async function sleep(ms: number): Promise<void> {
 62→  return new Promise(resolve => setTimeout(resolve, ms));
 63→}
 64→
 65→async function runScheduledSync(): Promise<void> {
 66→  console.log('[scheduler] Starting scheduled sync run');
 67→
 68→  const db = getAccountDb();
 69→
 70→  const rows = db.all(
 71→    `SELECT m.actual_account_id, m.eb_account_uid, m.session_id,
 72→            s.valid_until, s.aspsp_name
 73→     FROM eb_account_map m
 74→     JOIN eb_sessions s ON s.id = m.session_id
 75→     WHERE m.actual_account_id IS NOT NULL
 76→     ORDER BY m.session_id`,
 77→    [],
 78→  ) as unknown as AccountRow[];
 79→
 80→  // Group accounts by session so consent expiry is checked once per bank
 81→  // connection and one session's failure doesn't block other users.
 82→  const sessionGroups = new Map<string, AccountRow[]>();
 83→  for (const row of rows) {
 84→    const group = sessionGroups.get(row.session_id) ?? [];
 85→    group.push(row);
 86→    sessionGroups.set(row.session_id, group);
 87→  }
 88→
 89→  let totalSessions = 0;
 90→  let totalSynced = 0;
 91→  let totalErrors = 0;
 92→
 93→  for (const [sessionId, accounts] of sessionGroups) {
 94→    totalSessions++;
 95→    const aspspName = accounts[0]?.aspsp_name ?? 'unknown';
 96→    const validUntil = accounts[0]?.valid_until;
 97→
 98→    // Check consent expiry once per session group.
 99→    if (validUntil && new Date(validUntil) < new Date()) {
100→      console.log(
101→        `[scheduler] Skipping session ${sessionId} (${aspspName}): consent expired (${accounts.length} accounts)`,
102→      );
103→      continue;
104→    }
105→
106→    let successCount = 0;
107→
108→    for (const account of accounts) {
109→      try {
110→        await syncOneAccount(account);
111→        successCount++;
112→        totalSynced++;
113→      } catch (err) {
114→        if (err instanceof RateLimitError) {
115→          // A 429 applies to the entire API connection - don't sleep or retry.
116→          console.log(
117→            `[scheduler] Rate limited on session ${sessionId} (${aspspName}), skipping remaining accounts in session`,
118→          );
