 24→/**
 25→ * Checks whether Enable Banking is configured on the sync-server
 26→ * (JWT key present and valid).
 27→ *
 28→ * Returns:
 29→ * - configured: true when the server has a working Enable Banking key
 30→ * - isLoading: true while the status check is in flight
 31→ */
 32→export function useEnableBankingStatus() {
 33→  const [configured, setConfigured] = useState<boolean | null>(null);
 34→  const [isLoading, setIsLoading] = useState(false);
 35→  const status = useSyncServerStatus();
 36→
 37→  useEffect(() => {
 38→    async function fetch() {
 39→      setIsLoading(true);
 40→
 41→      const results = await send('enablebanking-status');
 42→
 43→      setConfigured(results?.configured || false);
 44→      setIsLoading(false);
 45→    }
 46→
 47→    if (status === 'online') {
 48→      fetch();
 49→    }
 50→  }, [status]);
 51→
 52→  return {
 53→    configured,
 54→    isLoading,
 55→  };
 56→}
