 58→type SyncStatusEntry = {
 59→  synced_at: string | null; // ISO string (server converts from epoch integer)
 60→  status: string;
 61→  error_message: string | null;
 62→  transactions_added: number | null; // from eb_sync_log
 63→  transactions_updated: number | null; // from eb_sync_log
 64→  error_code: string | null; // from eb_sync_log
 65→  consent_valid_until: string | null; // NEW - ISO date from eb_sessions.valid_until
 66→  session_id: string | null; // NEW - for re-auth grouping
 67→  aspsp_name: string | null; // NEW - for banner display (e.g. "ING Bank connection expires March 15")
 68→  aspsp_country: string | null; // NEW - for re-auth createAuth country param
 69→};
 70→
 71→/**
 72→ * Fetches per-account Enable Banking sync status from the sync-server.
 73→ * Accepts an array of Actual account UUIDs (the standard `account.id` field).
 74→ *
 75→ * CRITICAL DEPENDENCY: This hook works correctly because
 76→ * `eb_account_map.actual_account_id` is populated at link time by the
 77→ * `enablebanking-accounts-link` IPC handler (Plan 02-03 Task 2), which
 78→ * calls POST /update-account-map to store the Actual UUID in the map.
 79→ * The /transactions route then uses `mapRow.actual_account_id` from that
 80→ * map when writing to `eb_sync_log`. Without this link-time population,
 81→ * the `actual_account_id` column would be NULL and queries here would
 82→ * return no results.
 83→ *
 84→ * Returns:
 85→ * - statuses: Record<string, SyncStatusEntry> keyed by Actual account UUID
 86→ * - isLoading: true while the fetch is in flight
 87→ */
 88→export function useEnableBankingSyncStatus(accountIds: string[]) {
 89→  const [statuses, setStatuses] = useState<Record<string, SyncStatusEntry>>({});
 90→  const [isLoading, setIsLoading] = useState(false);
 91→
 92→  // Stable key to avoid re-fetching on every render when the array
 93→  // reference changes but contents are the same
 94→  const accountIdsKey = accountIds.join(',');
 95→
 96→  useEffect(() => {
 97→    if (accountIds.length === 0) {
 98→      setStatuses({});
 99→      return;
100→    }
101→
102→    async function fetch() {
103→      setIsLoading(true);
104→
105→      const result = await send('enablebanking-sync-status', { accountIds });
106→
107→      if (result && result.statuses) {
108→        setStatuses(result.statuses);
109→      } else {
110→        setStatuses({});
111→      }
112→
113→      setIsLoading(false);
114→    }
115→
116→    fetch();
117→    // eslint-disable-next-line react-hooks/exhaustive-deps
118→  }, [accountIdsKey]);
119→
120→  return {
121→    statuses,
122→    isLoading,
123→  };
124→}
125→
126→export type ConsentSession = {
127→  sessionId: string;
128→  aspspName: string | null;
129→  aspspCountry: string | null;
130→  validUntil: string | null;
131→  urgency: ConsentUrgency;
132→  accountIds: string[];
133→};
134→
135→/**
136→ * Self-contained hook that:
137→ * - Fetches all accounts via accountQueries.list()
138→ * - Filters to Enable Banking-linked accounts
139→ * - Groups by session_id with urgency calculation
140→ * - Returns sessions sorted by urgency (expired first)
141→ *
142→ * Urgency thresholds:
143→ * - expired: consent_valid_until is in the past
144→ * - urgent: within 7 days
145→ * - soon: within 14 days
146→ * - ok: more than 14 days away (not returned in sessions array)
147→ */
148→export function useConsentExpiry(): {
149→  sessions: ConsentSession[];
150→  worstUrgency: ConsentUrgency;
151→} {
152→  const { data: accounts } = useQuery(accountQueries.list());
153→
154→  const ebAccountIds = (accounts ?? [])
155→    .filter(a => a.account_sync_source === 'enableBanking')
156→    .map(a => a.id);
157→
158→  const { statuses } = useEnableBankingSyncStatus(ebAccountIds);
159→
160→  // Group accounts by session_id
161→  const sessionMap = new Map<string, ConsentSession>();
162→
163→  for (const accountId of ebAccountIds) {
164→    const entry = statuses[accountId];
165→    if (!entry || !entry.session_id) continue;
166→
167→    const sessionId = entry.session_id;
168→
169→    if (!sessionMap.has(sessionId)) {
170→      const validUntil = entry.consent_valid_until;
171→      let urgency: ConsentUrgency = 'ok';
172→
173→      if (validUntil) {
174→        const now = new Date();
175→        const expiry = new Date(validUntil);
176→        const msUntilExpiry = expiry.getTime() - now.getTime();
177→        const daysUntilExpiry = msUntilExpiry / (1000 * 60 * 60 * 24);
178→        urgency = getUrgencyLevel(daysUntilExpiry);
179→      }
180→
181→      sessionMap.set(sessionId, {
182→        sessionId,
183→        aspspName: entry.aspsp_name,
184→        aspspCountry: entry.aspsp_country,
185→        validUntil: entry.consent_valid_until,
186→        urgency,
187→        accountIds: [],
188→      });
189→    }
190→
191→    sessionMap.get(sessionId)!.accountIds.push(accountId);
192→  }
193→
194→  // Only surface sessions that need attention (not 'ok')
195→  const urgencyOrder: Record<ConsentUrgency, number> = {
196→    expired: 0,
197→    urgent: 1,
198→    soon: 2,
199→    ok: 3,
200→  };
201→
202→  const sessions = Array.from(sessionMap.values())
203→    .filter(s => s.urgency !== 'ok')
204→    .sort((a, b) => urgencyOrder[a.urgency] - urgencyOrder[b.urgency]);
205→
206→  const worstUrgency: ConsentUrgency =
207→    sessions.length > 0 ? sessions[0].urgency : 'ok';
208→
209→  return { sessions, worstUrgency };
210→}
