122→  const init = useEffectEvent(() => {
123→    // Wait a little bit to make sure the sync button will get the
124→    // sync start event. This can be improved later.
125→    setTimeout(async () => {
126→      await dispatch(sync());
127→
128→      // After CRDT sync completes, trigger background bank sync for accounts
129→      // whose last sync is older than the configurable stale threshold.
130→      // CRDT sync must finish first to avoid SQLite race conditions.
131→      try {
132→        const allAccounts = await send('accounts-get');
133→        const linkedAccounts = (allAccounts || []).filter(
134→          a => a.account_sync_source && a.account_id,
135→        );
136→        const effectiveThreshold = (staleThresholdHours ?? 6) * 60 * 60 * 1000;
137→        const now = Date.now();
138→
139→        // Fetch consent status in one call to filter out expired-consent
140→        // accounts before syncing (avoids wasted Enable Banking API calls).
