214→  // Bank sync check on visibility/focus changes. Lives in FinancesApp (not
215→  // App.tsx) because useLocalPref requires budget context - App.tsx renders
216→  // before any budget is loaded, so useLocalPref there produces the wrong
217→  // localStorage key ('undefined-bankSyncStaleThresholdHours').
218→  useEffect(() => {
219→    async function onVisibilityOrFocus() {
220→      // App.tsx already fires dispatch(sync()) (CRDT sync) on visibilitychange.
221→      // The two handlers run concurrently - this is acceptable because bank
222→      // sync reads from the EB API (not local DB) and is idempotent.
223→      if (document.hidden || isSyncingRef.current) return;
224→      isSyncingRef.current = true;
225→      try {
226→        const allAccounts = await send('accounts-get');
227→        const linkedAccounts = (allAccounts || []).filter(
228→          a => a.account_sync_source && a.account_id,
229→        );
230→        const effectiveThreshold = (staleThresholdHours ?? 6) * 60 * 60 * 1000;
231→        const now = Date.now();
232→
233→        const linkedIds = linkedAccounts.map(a => a.id);
234→        const syncStatuses =
235→          linkedIds.length > 0
236→            ? ((
237→                await send('enablebanking-sync-status', {
238→                  accountIds: linkedIds,
239→                })
240→              )?.statuses ?? {})
241→            : {};
242→
243→        const staleIds = linkedAccounts
244→          .filter(a => {
245→            const ebStatus = syncStatuses[a.id];
246→            if (
247→              ebStatus?.consent_valid_until &&
248→              new Date(ebStatus.consent_valid_until) <= new Date()
249→            ) {
250→              return false;
251→            }
252→            const lastSync = a.last_sync ? parseInt(a.last_sync, 10) : 0;
253→            return now - lastSync > effectiveThreshold;
254→          })
255→          .map(a => a.id);
256→
257→        if (staleIds.length > 0) {
258→          send('accounts-bank-sync', { ids: staleIds }).catch(() => {});
259→        }
260→      } catch {
261→        // Non-blocking: don't surface errors from background sync check
262→      } finally {
263→        isSyncingRef.current = false;
264→      }
265→    }
