267→    window.addEventListener('visibilitychange', onVisibilityOrFocus);
268→    window.addEventListener('focus', onVisibilityOrFocus);
269→    return () => {
270→      window.removeEventListener('visibilitychange', onVisibilityOrFocus);
271→      window.removeEventListener('focus', onVisibilityOrFocus);
272→    };
