  1→// [eb] Unit tests for syncAccountWithRetry exponential backoff helper.
  2→// Tests use dependency injection (syncFn, sleepFn mocks) to avoid real DB/API calls.
  3→import { describe, it, expect, vi, beforeEach } from 'vitest';
  4→
  5→import {
  6→  syncAccountWithRetry,
  7→  applyJitter,
  8→  type RetryPolicy,
  9→} from './scheduler.js';
 10→import {
 11→  RateLimitError,
 12→  SessionExpiredError,
 13→} from './app-enablebanking/errors.js';
 14→
 15→const testPolicy: RetryPolicy = {
 16→  maxRetries: 3,
 17→  initialDelay: 5000,
 18→  multiplier: 2,
 19→  maxDelay: 60000,
 20→  jitterFraction: 0.2,
 21→};
 22→
 23→describe('applyJitter', () => {
 24→  it('jitter keeps delay within +/-20% of nominal', () => {
 25→    for (let i = 0; i < 50; i++) {
 26→      const result = applyJitter(10000, 0.2);
 27→      expect(result).toBeGreaterThanOrEqual(8000);
 28→      expect(result).toBeLessThanOrEqual(12000);
 29→    }
 30→  });
 31→});
 32→
 33→describe('syncAccountWithRetry', () => {
 34→  let syncFn: ReturnType<typeof vi.fn<() => Promise<void>>>;
 35→  let sleepFn: ReturnType<typeof vi.fn<(ms: number) => Promise<void>>>;
 36→
 37→  beforeEach(() => {
 38→    syncFn = vi.fn<() => Promise<void>>();
 39→    sleepFn = vi.fn<(ms: number) => Promise<void>>().mockResolvedValue(undefined);
 40→  });
 41→
 42→  it('succeeds on first attempt without retry', async () => {
 43→    syncFn.mockResolvedValueOnce(undefined);
 44→
 45→    await syncAccountWithRetry(syncFn, sleepFn, testPolicy, 'test-account');
 46→
 47→    expect(syncFn).toHaveBeenCalledTimes(1);
 48→    expect(sleepFn).not.toHaveBeenCalled();
 49→  });
 50→
 51→  it('retries up to maxRetries on transient errors then succeeds', async () => {
 52→    const transientError = new Error('Network error');
 53→    syncFn
 54→      .mockRejectedValueOnce(transientError)
 55→      .mockRejectedValueOnce(transientError)
 56→      .mockResolvedValueOnce(undefined);
 57→
 58→    await syncAccountWithRetry(syncFn, sleepFn, testPolicy, 'test-account');
 59→
 60→    expect(syncFn).toHaveBeenCalledTimes(3);
 61→    expect(sleepFn).toHaveBeenCalledTimes(2);
 62→  });
 63→
 64→  it('propagates error after all retries exhausted', async () => {
 65→    const persistentError = new Error('Persistent failure');
 66→    syncFn.mockRejectedValue(persistentError);
 67→
 68→    await expect(
 69→      syncAccountWithRetry(syncFn, sleepFn, testPolicy, 'test-account'),
 70→    ).rejects.toThrow('Persistent failure');
 71→
 72→    // 1 initial + 3 retries = 4 total calls
 73→    expect(syncFn).toHaveBeenCalledTimes(4);
 74→  });
 75→
 76→  it('exponential backoff delays are approximately 5000, 10000, 20000', async () => {
 77→    syncFn.mockRejectedValue(new Error('fail'));
 78→
 79→    await expect(
 80→      syncAccountWithRetry(syncFn, sleepFn, testPolicy, 'test-account'),
 81→    ).rejects.toThrow();
 82→
 83→    expect(sleepFn).toHaveBeenCalledTimes(3);
 84→    const delays = sleepFn.mock.calls.map((call: unknown[]) => call[0] as number);
 85→
 86→    // 1st sleep: nominal 5000, +/-20% -> 4000 to 6000
 87→    expect(delays[0]).toBeGreaterThanOrEqual(4000);
 88→    expect(delays[0]).toBeLessThanOrEqual(6000);
 89→
 90→    // 2nd sleep: nominal 10000, +/-20% -> 8000 to 12000
 91→    expect(delays[1]).toBeGreaterThanOrEqual(8000);
 92→    expect(delays[1]).toBeLessThanOrEqual(12000);
 93→
 94→    // 3rd sleep: nominal 20000, +/-20% -> 16000 to 24000
 95→    expect(delays[2]).toBeGreaterThanOrEqual(16000);
 96→    expect(delays[2]).toBeLessThanOrEqual(24000);
 97→  });
 98→
 99→  it('RateLimitError propagates immediately without sleeping', async () => {
100→    syncFn.mockRejectedValue(new RateLimitError('rate limited'));
101→
102→    await expect(
103→      syncAccountWithRetry(syncFn, sleepFn, testPolicy, 'test-account'),
104→    ).rejects.toBeInstanceOf(RateLimitError);
105→
106→    expect(sleepFn).not.toHaveBeenCalled();
